65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
74	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
75	     * stored lower-cased.
76	     */
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
79	
80	    /** A well-formed postcode: exactly four digits. */
81	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
82	
83	    /**
84	     * Email domains belonging to disposable-address providers. An owner whose email domain (the part
85	     * after the '@', compared case-insensitively) is one of these is rejected: such addresses are
86	     * throwaway and unsuitable for a durable owner record.
87	     */
88	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
89	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
90	
91	    /**
92	     * Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. A postcode supplied for an
93	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
94	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
95	     */
96	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
97	        "NSW", new int[] {2000, 2099},
98	        "VIC", new int[] {3000, 3099},
99	        "QLD", new int[] {4000, 4099});
100	
101	    /** Dedicated audit logger; one line is emitted per successful owner create. */
102	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
103	
104	    /**
105	     * The maximum number of owners a single city may contain. Once a city already holds this many
106	     * owners, any further create naming that city is rejected as a conflict.
107	     */
108	    private static final int MAX_OWNERS_PER_CITY = 50;
109	
110	    /**
111	     * The maximum number of owners that may be registered in a single day. Once this many owners
112	     * already carry today's registration date, any further create is rejected as too many requests.
113	     */
114	    private static final int MAX_OWNERS_PER_DAY = 100;
115	
116	    /**
117	     * The number of owners that must already be registered on today's business day before a response
118	     * carries a bulk-signup warning. Once more than this many owners already carry today's
119	     * registration date, responses set {@code bulkSignupWarning} true.
120	     */
121	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
122	
123	    /**
124	     * The fixed list of public holidays. A registration date that lands on one of these dates is
125	     * rolled forward to the next non-holiday business day, just as a weekend date is.
126	     */
127	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
128	        LocalDate.of(2026, 1, 1),
129	        LocalDate.of(2026, 1, 26),
130	        LocalDate.of(2026, 4, 25),
131	        LocalDate.of(2026, 12, 25),
132	        LocalDate.of(2026, 12, 28));
133	
134	    private final ClinicService clinicService;
135	
136	    private final OwnerMapper ownerMapper;
137	
138	    private final PetMapper petMapper;
139	
140	    private final VisitMapper visitMapper;
141	
142	    public OwnerRestControllerV1(ClinicService clinicService,
143	                                 OwnerMapper ownerMapper,
144	                                 PetMapper petMapper,
145	                                 VisitMapper visitMapper) {
146	        this.clinicService = clinicService;
147	        this.ownerMapper = ownerMapper;
148	        this.petMapper = petMapper;
149	        this.visitMapper = visitMapper;
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
155	        Collection<Owner> owners;
156	        if (lastName != null) {
157	            owners = this.clinicService.findOwnerByLastName(lastName);
158	        } else {
159	            owners = this.clinicService.findAllOwners();
160	        }
161	        if (owners.isEmpty()) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
165	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        OwnerDto ownerDto = toOwnerDto(owner);
176	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
177	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
183	        validateRequiredOwnerFields(ownerFieldsDto);
184	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
185	        LocalDate suppliedOrDefaultDate =
186	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
187	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
188	        rejectDailyLimitExceeded(registrationDate);
189	        rejectCityAtCapacity(ownerFieldsDto.getCity());
190	        HttpHeaders headers = new HttpHeaders();
191	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
192	        validatePostcode(owner.getCity(), owner.getPostcode());
193	        applyAddress(owner);
194	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
195	        owner.setTelephone(normalizedTelephone);
196	        boolean declaredHouseholdMember = applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
197	        owner.setEmail(normalizeEmail(owner.getEmail()));
198	        rejectDuplicateIdentity(owner);
199	        applyPossibleDuplicate(owner, declaredHouseholdMember);
200	        owner.setRegistrationDate(registrationDate);
201	        owner.setCustomerCode(
202	            generateCustomerCode(owner.getPostcode(), owner.getCity(), normalizedTelephone, owner.getLastName()));
203	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
204	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
205	        this.clinicService.saveOwner(owner);
206	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
207	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
208	            owner.getMembershipNumber());
209	        OwnerDto ownerDto = toOwnerDto(owner);
210	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
211	        headers.setLocation(UriComponentsBuilder.newInstance()
212	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
213	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
219	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
220	        if (currentOwner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        currentOwner.setAddress(ownerFieldsDto.getAddress());
224	        currentOwner.setCity(ownerFieldsDto.getCity());
225	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
226	        currentOwner.setLastName(ownerFieldsDto.getLastName());
227	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
228	        this.clinicService.saveOwner(currentOwner);
229	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Transactional
234	    @Override
235	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
236	        Owner owner = this.clinicService.findOwnerById(ownerId);
237	        if (owner == null) {
238	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	        }
240	        owner.setDeleted(true);
241	        this.clinicService.saveOwner(owner);
242	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        HttpHeaders headers = new HttpHeaders();
253	        Pet pet = petMapper.toPet(petFieldsDto);
254	        owner.setId(ownerId);
255	        pet.setOwner(owner);
256	        pet.getType().setName(null);
257	        this.clinicService.savePet(pet);
258	        PetDto petDto = petMapper.toPetDto(pet);
259	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
260	            .buildAndExpand(pet.getId()).toUri());
261	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
267	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
268	        if (currentOwner != null) {
269	            Pet currentPet = this.clinicService.findPetById(petId);
270	            if (currentPet != null) {
271	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
272	                currentPet.setName(petFieldsDto.getName());
273	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
274	                this.clinicService.savePet(currentPet);
275	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
276	            }
277	        }
278	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
284	        HttpHeaders headers = new HttpHeaders();
285	        Visit visit = visitMapper.toVisit(visitFieldsDto);
286	        Pet pet = new Pet();
287	        pet.setId(petId);
288	        visit.setPet(pet);
289	        this.clinicService.saveVisit(visit);
290	        VisitDto visitDto = visitMapper.toVisitDto(visit);
291	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
292	            .buildAndExpand(visit.getId()).toUri());
293	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
294	    }
295	
296	
297	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
298	    @Override
299	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
300	        Owner owner = this.clinicService.findOwnerById(ownerId);
301	        if (owner != null) {
302	            Pet pet = owner.getPet(petId);
303	            if (pet != null) {
304	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
305	            }
306	        }
307	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
308	    }
309	
310	    /**
311	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
312	     * offending field is collected so the caller learns exactly which values must be supplied.
313	     *
314	     * @param ownerFieldsDto the submitted owner payload
315	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
316	     *         telephone is missing or blank
317	     */
318	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
319	        List<String> missingFields = new ArrayList<>();
320	        if (isBlank(ownerFieldsDto.getFirstName())) {
321	            missingFields.add("firstName");
322	        }
323	        if (isBlank(ownerFieldsDto.getLastName())) {
324	            missingFields.add("lastName");
325	        }
326	        if (isBlank(ownerFieldsDto.getAddressLine1())
327	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
328	            missingFields.add("address");
329	        }
330	        if (isBlank(ownerFieldsDto.getCity())) {
331	            missingFields.add("city");
332	        }
333	        if (isBlank(ownerFieldsDto.getTelephone())) {
334	            missingFields.add("telephone");
335	        }
336	        if (!missingFields.isEmpty()) {
337	            throw new MissingOwnerFieldsException(missingFields);
338	        }
339	    }
340	
341	    private boolean isBlank(String value) {
342	        return value == null || value.isBlank();
343	    }
344	
345	    /**
346	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
347	     * current date. A registration date may not lie in the future; a value equal to today or in the
348	     * past is accepted, and an absent date is left to default to the server date.
349	     *
350	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
351	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
352	     */
353	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
354	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
355	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
356	        }
357	    }
358	
359	    /**
360	     * Counts the existing owners who, before this create, already share the given first and last name.
361	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
362	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
363	     * case or spacing still count as the same name.
364	     *
365	     * @param firstName the first name of the owner being created
366	     * @param lastName the last name of the owner being created
367	     * @return the number of existing owners sharing both names (zero when none)
368	     */
369	    private int countNamesakes(String firstName, String lastName) {
370	        String first = normalizeHouseholdField(firstName);
371	        String last = normalizeHouseholdField(lastName);
372	        return (int) this.clinicService.findAllOwners().stream()
373	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
374	                && normalizeHouseholdField(existing.getLastName()).equals(last))
375	            .count();
376	    }
377	
378	    /**
379	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
380	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
381	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
382	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
383	     * more owners the create is rejected as a conflict.
384	     *
385	     * @param city the city of the owner being created
386	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
387	     */
388	    /**
389	     * Rejects an owner create once the maximum number of owners have already been registered on the
390	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
391	     * which is always a business day (a weekend effective date is rolled forward to the following
392	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
393	     * business day the create is rejected as too many requests. Because a weekend effective date is
394	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
395	     *
396	     * @param businessDay the adjusted business day the owner being created would be registered on
397	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
398	     */
399	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
400	        long ownersOnDay = this.clinicService.findAllOwners().stream()
401	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
402	            .count();
403	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
404	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
405	        }
406	    }
407	
408	    /**
409	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
410	     * forward, and a date that lands on a listed public holiday is likewise rolled forward, until the
411	     * result is a weekday that is not a public holiday; a weekday that is not a holiday is returned
412	     * unchanged. This applies whether the date was supplied on the request or defaulted to the
413	     * server's current date.
414	     *
415	     * @param date the effective registration date (supplied or defaulted)
416	     * @return the first non-holiday weekday on or after the supplied date
417	     */
418	    /**
419	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
420	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
421	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
422	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
423	     *
424	     * @return {@code true} when more than the threshold number of owners are already registered on
425	     *         today's business day, otherwise {@code false}
426	     */
427	    private boolean isBulkSignupWarningActive() {
428	        LocalDate today = toBusinessDay(LocalDate.now());
429	        long ownersToday = this.clinicService.findAllOwners().stream()
430	            .filter(existing -> today.equals(existing.getRegistrationDate()))
431	            .count();
432	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
433	    }
434	
435	    private LocalDate toBusinessDay(LocalDate date) {
436	        LocalDate adjusted = switch (date.getDayOfWeek()) {
437	            case SATURDAY -> date.plusDays(2);
438	            case SUNDAY -> date.plusDays(1);
439	            default -> date;
440	        };
441	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
442	            adjusted = adjusted.plusDays(1);
443	        }
444	        return adjusted;
445	    }
446	
447	    private boolean isWeekend(LocalDate date) {
448	        return switch (date.getDayOfWeek()) {
449	            case SATURDAY, SUNDAY -> true;
450	            default -> false;
451	        };
452	    }
453	
454	    private void rejectCityAtCapacity(String city) {
455	        String normalizedCity = normalizeHouseholdField(city);
456	        long ownersInCity = this.clinicService.findAllOwners().stream()
457	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
458	            .count();
459	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
460	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
461	        }
462	    }
463	
464	    /**
465	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
466	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
467	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
468	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). Two owners resolve
469	     * to the same base code only when they share a region and produce the same telephone-and-last-name
470	     * hash; when the computed code collides with an existing owner's customer code it is de-duplicated
471	     * by appending '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
472	     *
473	     * @param postcode the owner's postcode, used first to derive the region
474	     * @param city the owner's city, used to derive the region when the postcode maps to none
475	     * @param normalizedTelephone the owner's normalized (E.164) telephone
476	     * @param lastName the owner's last name
477	     * @return the formatted, de-duplicated customer code
478	     */
479	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
480	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
481	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
482	        String baseCode = region + "-" + hash8;
483	        return deduplicateCustomerCode(baseCode);
484	    }
485	
486	    /**
487	     * De-duplicates a computed customer code against every existing owner's customer code. When no
488	     * existing owner already carries the base code it is returned unchanged; otherwise '-&lt;n&gt;' is
489	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner holds.
490	     *
491	     * @param baseCode the computed, formatted customer code before de-duplication
492	     * @return the base code when unique, otherwise the base code suffixed with '-&lt;n&gt;'
493	     */
494	    private String deduplicateCustomerCode(String baseCode) {
495	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
496	            .map(Owner::getCustomerCode)
497	            .filter(java.util.Objects::nonNull)
498	            .collect(java.util.stream.Collectors.toSet());
499	        if (!existingCodes.contains(baseCode)) {
500	            return baseCode;
501	        }
502	        int n = 2;
503	        while (existingCodes.contains(baseCode + "-" + n)) {
504	            n++;
505	        }
506	        return baseCode + "-" + n;
507	    }
508	
509	    /**
510	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
511	     * customerCode is the owner's customer code and YY is the last two digits of the fiscal year (the
512	     * fiscal year starts on 1 July) that the business-day-adjusted registrationDate falls in
513	     * (e.g. 'NSW-1A2B3C4D-M27').
514	     *
515	     * @param customerCode the owner's customer code
516	     * @param registrationDate the owner's business-day-adjusted registration date
517	     * @return the formatted membership number
518	     */
519	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
520	        String yy = String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
521	        return customerCode + "-M" + yy;
522	    }
523	
524	    /**
525	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
526	     * country calling code. Australia ('+61') uses 9 national digits and the North American
527	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
528	     * E.164 length (8 to 15 digits overall).
529	     */
530	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
531	        java.util.Map.of("61", 9, "1", 10);
532	
533	    /**
534	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
535	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
536	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
537	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
538	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
539	     * E.164 string is what gets stored and returned.
540	     *
541	     * @param telephone the raw telephone value from the request
542	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
543	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
544	     *         national number has the wrong length for its country code
545	     */
546	    private String normalizeTelephone(String telephone) {
547	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
548	        String e164;
549	        if (cleaned.startsWith("+")) {
550	            e164 = cleaned;
551	        } else {
552	            String national = cleaned;
553	            if (national.startsWith("0")) {
554	                national = national.substring(1);
555	            }
556	            e164 = "+61" + national;
557	        }
558	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
559	            throw new InvalidOwnerFieldsException(List.of("telephone"));
560	        }
561	        validateNationalNumberLength(e164);
562	        return e164;
563	    }
564	
565	    /**
566	     * Rejects an E.164 telephone whose national number does not have the exact length its country
567	     * calling code requires. The digits after the leading '+' are split into the longest matching
568	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
569	     * code is known and the national number's length differs from the required count the telephone is
570	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
571	     *
572	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
573	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
574	     */
575	    private void validateNationalNumberLength(String e164) {
576	        String digits = e164.substring(1);
577	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
578	            String countryCode = digits.substring(0, codeLength);
579	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
580	            if (requiredNationalLength != null) {
581	                int nationalLength = digits.length() - codeLength;
582	                if (nationalLength != requiredNationalLength) {
583	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
584	                }
585	                return;
586	            }
587	        }
588	    }
589	
590	    /**
591	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
592	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
593	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
594	     * stored and returned is the value lower-cased.
595	     *
596	     * @param email the raw email value from the request, or {@code null} when none was supplied
597	     * @return the lower-cased email, or {@code null} when no email was supplied
598	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
599	     *         its domain is on the disposable-domain blocklist
600	     */
601	    private String normalizeEmail(String email) {
602	        if (email == null || email.isBlank()) {
603	            return null;
604	        }
605	        if (!EMAIL_PATTERN.matcher(email).matches()) {
606	            throw new InvalidOwnerFieldsException(List.of("email"));
607	        }
608	        String normalized = email.toLowerCase(Locale.ROOT);
609	        String domain = normalized.substring(normalized.indexOf('@') + 1);
610	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
611	            throw new InvalidOwnerFieldsException(List.of("email"));
612	        }
613	        return normalized;
614	    }
615	
616	    /**
617	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
618	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
619	     * When present it must be exactly four digits and, when the owner's city maps to a known region
620	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
621	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
622	     * region accepts any four-digit postcode.
623	     *
624	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
625	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
626	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
627	     *         for the city's region
628	     */
629	    private void validatePostcode(String city, String postcode) {
630	        if (postcode == null || postcode.isBlank()) {
631	            return;
632	        }
633	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
634	            throw new InvalidOwnerFieldsException(List.of("postcode"));
635	        }
636	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
637	        if (range == null) {
638	            return;
639	        }
640	        int value = Integer.parseInt(postcode);
641	        if (value < range[0] || value > range[1]) {
642	            throw new InvalidOwnerFieldsException(List.of("postcode"));
643	        }
644	    }
645	
646	    /**
647	     * Resolves an owner's address from the supplied structured and flat fields, preferring the
648	     * structured form. Whichever address fields were supplied are normalized (see
649	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
650	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (an
651	     * absent or blank {@code addressLine2} is cleared) and the composed {@code address} is the
652	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
653	     * appended when the latter is present. When no {@code addressLine1} is supplied the flat
654	     * {@code address} is used unchanged for backward compatibility and the structured lines are
655	     * cleared. The composed {@code address} is what every later step reads.
656	     *
657	     * @param owner the owner being created, mapped from the request but not yet normalized
658	     */
659	    private void applyAddress(Owner owner) {
660	        String line1 = normalizeAddress(owner.getAddressLine1());
661	        String line2 = normalizeAddress(owner.getAddressLine2());
662	        String flat = normalizeAddress(owner.getAddress());
663	        if (!line1.isEmpty()) {
664	            owner.setAddressLine1(line1);
665	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
666	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
667	        } else {
668	            owner.setAddressLine1(null);
669	            owner.setAddressLine2(null);
670	            owner.setAddress(flat);
671	        }
672	    }
673	
674	    /**
675	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
676	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
677	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
678	     * normalized form is what gets stored, returned and used for every address comparison (the
679	     * required-field check, household duplicate detection and the shared household id).
680	     *
681	     * @param address the raw address value from the request, or {@code null}
682	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
683	     */
684	    private String normalizeAddress(String address) {
685	        if (address == null) {
686	            return "";
687	        }
688	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
689	        if (collapsed.isEmpty()) {
690	            return "";
691	        }
692	        String[] tokens = collapsed.split(" ");
693	        for (int i = 0; i < tokens.length; i++) {
694	            switch (tokens[i]) {
695	                case "ST" -> tokens[i] = "STREET";
696	                case "RD" -> tokens[i] = "ROAD";
697	                case "AVE" -> tokens[i] = "AVENUE";
698	                default -> { }
699	            }
700	        }
701	        return String.join(" ", tokens);
702	    }
703	
704	    /**
705	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
706	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
707	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
708	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
709	     * so two members of one household with different telephones have different keys and are both
710	     * allowed; only an owner whose entire key is identical is a duplicate.
711	     *
712	     * @param owner the owner being created, with its telephone, email and householdId already resolved
713	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
714	     */
715	    private void rejectDuplicateIdentity(Owner owner) {
716	        String identityKey = owner.getIdentityKey();
717	        boolean inUse = this.clinicService.findAllOwners().stream()
718	            .filter(existing -> !existing.isDeleted())
719	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
720	        if (inUse) {
721	            throw new DuplicateOwnerIdentityException(identityKey);
722	        }
723	    }
724	
725	    /**
726	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
727	     * that shares this owner's last name (compared case-insensitively with collapsed whitespace) and
728	     * postcode but carries a different (normalized) telephone; such an owner is not a hard duplicate
729	     * (its identity key differs) and is still created. When at least one soft match exists,
730	     * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the lowest-id match;
731	     * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
732	     * <p>
733	     * A declared household member - an owner that acknowledged sharing an existing household via
734	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
735	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
736	     *
737	     * @param owner the owner being created, with its last name, postcode and normalized telephone resolved
738	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
739	     */
740	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
741	        if (declaredHouseholdMember) {
742	            owner.setPossibleDuplicate(false);
743	            return;
744	        }
745	        String lastName = normalizeHouseholdField(owner.getLastName());
746	        String postcode = owner.getPostcode();
747	        String telephone = owner.getTelephone();
748	        Owner match = null;
749	        if (postcode != null && !postcode.isBlank()) {
750	            match = this.clinicService.findAllOwners().stream()
751	                .filter(existing -> !existing.isDeleted())
752	                .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName))
753	                .filter(existing -> postcode.equals(existing.getPostcode()))
754	                .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
755	                .min(java.util.Comparator.comparing(Owner::getId))
756	                .orElse(null);
757	        }
758	        if (match != null) {
759	            owner.setPossibleDuplicate(true);
760	            owner.setPossibleDuplicateOf(match.getId());
761	        } else {
762	            owner.setPossibleDuplicate(false);
763	        }
764	    }
765	
766	    /**
767	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
768	     * household member count} for the response.
769	     *
770	     * @param owner the owner to map
771	     * @return the mapped owner DTO
772	     */
773	    private OwnerDto toOwnerDto(Owner owner) {
774	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
775	        return ownerMapper.toOwnerDto(owner);
776	    }
777	
778	    /**
779	     * Counts the members of the given owner's household - the owners that share this owner's
780	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
781	     * is {@code null}) is its own sole member, so the count is one.
782	     *
783	     * @param owner the owner whose household is being sized
784	     * @return the number of owners sharing this owner's household (one when it has no household)
785	     */
786	    private int countHouseholdMembers(Owner owner) {
787	        String householdId = owner.getHouseholdId();
788	        if (householdId == null) {
789	            return 1;
790	        }
791	        return (int) this.clinicService.findAllOwners().stream()
792	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
793	            .count();
794	    }
795	
796	    /**
797	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
798	     * last name and a postcode: the {@code householdId} is derived deterministically from the
799	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
800	     * owners with the same last name and postcode always resolve to the same identifier and belong to
801	     * the same household automatically - no acknowledgement is needed to create the link.
802	     * <p>
803	     * When the owner supplies a postcode its {@code householdId} is always assigned. If that household
804	     * already has at least one member, the create is a household duplicate: it is rejected with a 409
805	     * unless {@code sharesHousehold} is true, in which case the owner is created as a declared member
806	     * of that household. An owner with no postcode belongs to no household and is left without an
807	     * identifier.
808	     *
809	     * @param owner the owner being created
810	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
811	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
812	     *         {@code false}
813	     * @throws DuplicateOwnerHouseholdException when the household already exists and the create did not
814	     *         acknowledge it via {@code sharesHousehold}
815	     */
816	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
817	        String postcode = owner.getPostcode();
818	        if (postcode == null || postcode.isBlank()) {
819	            return false;
820	        }
821	        String lastName = normalizeHouseholdField(owner.getLastName());
822	        String householdId = generateHouseholdId(lastName, postcode);
823	        owner.setHouseholdId(householdId);
824	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
825	            .filter(existing -> !existing.isDeleted())
826	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
827	        if (!hasExistingMember) {
828	            return false;
829	        }
830	        if (!Boolean.TRUE.equals(sharesHousehold)) {
831	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), postcode);
832	        }
833	        return true;
834	    }
835	
836	    /**
837	     * Builds the stable identifier shared by the members of one household. It is derived purely from
838	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
839	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
840	     * two fields joined by a single '|'.
841	     *
842	     * @param normalizedLastName the household's last name, already normalized for comparison
843	     * @param postcode the household's postcode
844	     * @return the shared household identifier
845	     */
846	    private String generateHouseholdId(String normalizedLastName, String postcode) {
847	        String key = normalizedLastName + '|' + postcode;
848	        try {
849	            byte[] digest = MessageDigest.getInstance("SHA-256")
850	                .digest(key.getBytes(StandardCharsets.UTF_8));
851	            StringBuilder hex = new StringBuilder();
852	            for (byte b : digest) {
853	                hex.append(String.format("%02X", b));
854	                if (hex.length() >= 12) {
855	                    break;
856	                }
857	            }
858	            return hex.substring(0, 12);
859	        } catch (NoSuchAlgorithmException e) {
860	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
861	        }
862	    }
863	
864	    /**
865	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
866	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
867	     * the owner's normalized telephone and last name.
868	     *
869	     * @param input the string to digest
870	     * @param length the number of leading upper-case hex characters to return
871	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
872	     */
873	    private String sha256UpperHex(String input, int length) {
874	        try {
875	            byte[] digest = MessageDigest.getInstance("SHA-256")
876	                .digest(input.getBytes(StandardCharsets.UTF_8));
877	            StringBuilder hex = new StringBuilder();
878	            for (byte b : digest) {
879	                hex.append(String.format("%02X", b));
880	                if (hex.length() >= length) {
881	                    break;
882	                }
883	            }
884	            return hex.substring(0, length);
885	        } catch (NoSuchAlgorithmException e) {
886	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
887	        }
888	    }
889	
890	    /**
891	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
892	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
893	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
894	     * expands common abbreviations.
895	     *
896	     * @param value the raw last name, or {@code null}
897	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
898	     */
899	    private String normalizeHouseholdField(String value) {
900	        if (value == null) {
901	            return "";
902	        }
903	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
904	    }
905	}
